// Loopback-only transport test. Generated bytes never enter the clip catalog.
import {createServer} from 'node:http';
import {mkdtemp,writeFile,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join,resolve,sep} from 'node:path';
import assert from 'node:assert/strict';
import {downloadVideo} from '../packages/pipeline/src/ytdlp.ts';
const root=await mkdtemp(join(tmpdir(),'clipforge-rate-'));
const rateLimitKbps=Number(process.argv[3]??10000);
const size=10_000_000,block=Buffer.alloc(64*1024,1);
let delivered=0,active=0,maxActive=0;
const server=createServer((req,res)=>{
  const start=Number(req.headers.range?.match(/bytes=(\d+)-/)?.[1]??0);
  res.writeHead(start?206:200,{'content-type':'video/mp4','content-length':size-start,'accept-ranges':'bytes',...(start?{'content-range':`bytes ${start}-${size-1}/${size}`}:{})});
  if(req.method==='HEAD'){res.end();return;}
  let sent=start;active++;maxActive=Math.max(maxActive,active);
  res.on('close',()=>active--);
  const pump=()=>{while(sent<size&&!res.destroyed){const bytes=block.subarray(0,Math.min(block.length,size-sent));sent+=bytes.length;delivered+=bytes.length;if(!res.write(bytes)){res.once('drain',pump);return;}}res.end();};pump();
});
await new Promise(r=>server.listen(0,'127.0.0.1',r));
try {
  const start=Date.now();
  await Promise.all(['one','two'].map(name=>downloadVideo(`http://127.0.0.1:${server.address().port}/${name}.mp4`,join(root,`${name}.mp4`),'best',8,
    {command:process.argv[2]??'.venv/Scripts/python.exe',args:['-m','yt_dlp'],rateLimitKbps})));
  const elapsed=(Date.now()-start)/1000,rate=size*2*8/elapsed/1000;
  assert(rate<=rateLimitKbps,`Aggregate rate exceeds cap: ${rate}`);
  // Extractor probes can overlap a completed response's close event. Actual
  // media transfers are serialized by downloadVideo's process-wide lane.
  const result={bytes:size*2,elapsedSeconds:elapsed,averageKbps:Math.round(rate),limitKbps:rateLimitKbps,maxOpenResponses:maxActive,deliveredWithProbes:delivered};
  await writeFile('data/reviews/download-loopback.json',JSON.stringify(result,null,2));console.log(result);
}finally{
  server.closeAllConnections();await new Promise(r=>server.close(r));
  assert(resolve(root).startsWith(resolve(tmpdir())+sep+'clipforge-rate-'));
  await rm(root,{recursive:true,force:true});
}
